import json

def pathfind():
    # Read parameters directly from the globally defined input_data dictionary
    global input_data
    start_x = int(input_data['start_x'])
    start_y = int(input_data['start_y'])
    target_x = int(input_data['target_x'])
    target_y = int(input_data['target_y'])

    default_w = int(input_data.get('map_width', 10))
    default_h = int(input_data.get('map_height', 12))

    map_width = max(default_w, start_x + 5, target_x + 5)
    map_height = max(default_h, start_y + 5, target_y + 5)

    blocked_tiles = set()
    for tile in input_data.get('blocked_tiles', []):
        blocked_tiles.add((int(tile[0]), int(tile[1])))

    for rect in input_data.get('rectangular_obstacles', []):
        x1, y1, x2, y2 = map(int, rect)
        for x in range(min(x1, x2), max(x1, x2) + 1):
            for y in range(min(y1, y2), max(y1, y2) + 1):
                blocked_tiles.add((x, y))

    if start_x < 0 or start_y < 0 or target_x < 0 or target_y < 0:
        print("Error: Negative coordinates are not allowed.")
        return []

    if (start_x, start_y) == (target_x, target_y):
        print("[]")
        return []

    from collections import deque
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    directions = [
        ('Up', (0, -1)),
        ('Down', (0, 1)),
        ('Left', (-1, 0)),
        ('Right', (1, 0))
    ]

    path_found = False
    buttons = []

    while queue:
        curr_x, curr_y, curr_path = queue.popleft()

        if (curr_x, curr_y) == (target_x, target_y):
            path_found = True
            buttons = curr_path
            break

        for btn, (dx, dy) in directions:
            nx, ny = curr_x + dx, curr_y + dy
            if 0 <= nx < map_width and 0 <= ny < map_height:
                if (nx, ny) not in blocked_tiles and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, curr_path + [btn]))

    if path_found:
        print(json.dumps(buttons))
    else:
        print("Error: No path found between start and target coordinates.")
        return []

if __name__ == '__main__':
    pathfind()
